INSERT INTO `hr_document_templates` VALUES
(1,'Offer Letter','Offer Letter','Employment Offer Letter - {{company_name}}','<div style=\"font-family: \'DejaVu Sans\', sans-serif; font-size: 13px; line-height: 1.6;\">\n    <table style=\"width: 100%; table-layout: fixed; word-wrap: break-word; border-bottom: 1.5px solid #1e3a8a; margin-bottom: 20px; padding-bottom: 10px;\">\n        <tr>\n            <td style=\"vertical-align: top;\">\n                <p style=\"margin: 0; font-size: 13px;\"><strong>Ref No:</strong> {{document_number}}</p>\n                <p style=\"margin: 0; font-size: 13px;\"><strong>Date:</strong> {{current_date}}</p>\n            </td>\n            <td style=\"text-align: right; vertical-align: top;\">\n                <p style=\"margin: 0; font-size: 13px;\"><strong>Location:</strong> {{work_location}}</p>\n            </td>\n        </tr>\n    </table>\n\n    <p style=\"margin-bottom: 15px;\">\n        <strong>To,</strong><br>\n        <strong>Name:</strong> {{employee_name}}<br>\n        <strong>Employee Code:</strong> {{employee_id}}<br>\n        <strong>Email:</strong> {{email}}<br>\n        <strong>Contact:</strong> {{mobile}}\n    </p>\n\n    <p>Dear <strong>{{employee_name}}</strong>,</p>\n\n    <p>With reference to your application and subsequent interview, we are pleased to offer you appointment as <strong>{{designation}}</strong> in the <strong>{{department}}</strong> department at <strong>{{company_name}}</strong> under the following terms and conditions:</p>\n\n    <div class=\"section\"><h4 style=\"color: #0f172a; background-color: #f1f5f9; border-left: 3px solid #1e3a8a; padding: 4px 8px; padding-bottom: 4px; margin-top: 15px;\">1. POSITION & EMPLOYMENT DETAILS</h4>\n    <table style=\"width: 100%; table-layout: fixed; word-wrap: break-word; border-collapse: collapse; margin-bottom: 15px;\">\n        <tr><td style=\"padding: 5px 8px; border: 1px solid #d9d9d9; width: 40%;\"><strong>Designation:</strong></td><td>{{designation}}</td></tr>\n        <tr><td style=\"padding: 5px 8px; border: 1px solid #d9d9d9;\"><strong>Department:</strong></td><td>{{department}}</td></tr>\n        <tr><td style=\"padding: 5px 8px; border: 1px solid #d9d9d9;\"><strong>Employment Type:</strong></td><td>{{employment_type}}</td></tr>\n        <tr><td style=\"padding: 5px 8px; border: 1px solid #d9d9d9;\"><strong>Date of Joining:</strong></td><td>{{joining_date}}</td></tr>\n        <tr><td style=\"padding: 5px 8px; border: 1px solid #d9d9d9;\"><strong>Work Location:</strong></td><td>{{work_location}}</td></tr>\n        <tr><td style=\"padding: 5px 8px; border: 1px solid #d9d9d9;\"><strong>Reporting Manager:</strong></td><td>{{reporting_manager}}</td></tr>\n        <tr><td style=\"padding: 5px 8px; border: 1px solid #d9d9d9;\"><strong>Working Hours:</strong></td><td>{{working_hours}}</td></tr>\n        <tr><td style=\"padding: 5px 8px; border: 1px solid #d9d9d9;\"><strong>Probation Period:</strong></td><td>{{probation_period}}</td></tr>\n        <tr><td style=\"padding: 5px 8px; border: 1px solid #d9d9d9;\"><strong>Total Remuneration (Annual CTC):</strong></td><td><strong>{{salary}}</strong></td></tr>\n    </table></div>\n\n    <div class=\"section\"><h4 style=\"color: #0f172a; background-color: #f1f5f9; border-left: 3px solid #1e3a8a; padding: 4px 8px; padding-bottom: 4px; margin-top: 15px;\">2. PROBATION & PERFORMANCE</h4>\n    <p>You will be on probation for a period of <strong>{{probation_period}}</strong> from your date of joining. Upon successful completion of probation and performance evaluation, your services will be confirmed in writing.</p></div>\n\n    <div class=\"section\"><h4 style=\"color: #0f172a; background-color: #f1f5f9; border-left: 3px solid #1e3a8a; padding: 4px 8px; padding-bottom: 4px; margin-top: 15px;\">3. CONFIDENTIALITY & NON-DISCLOSURE</h4>\n    <p>You shall maintain strict confidentiality regarding all company trade secrets, proprietary algorithms, client lists, software assets, and business operational strategies during and after your tenure at <strong>{{company_name}}</strong>.</p></div>\n\n    <div class=\"section\"><h4 style=\"color: #0f172a; background-color: #f1f5f9; border-left: 3px solid #1e3a8a; padding: 4px 8px; padding-bottom: 4px; margin-top: 15px;\">4. ACCEPTANCE OF OFFER</h4>\n    <p>Please sign and return the duplicate copy of this offer letter as a formal token of your acceptance of the terms and conditions outlined above.</p></div>\n\n    <p style=\"margin-top: 25px;\">Welcome to <strong>{{company_name}}</strong>! We look forward to a rewarding professional relationship.</p>\n\n    <br>\n    <table style=\"width: 100%; table-layout: fixed; word-wrap: break-word; margin-top: 20px;\">\n        <tr>\n            <td style=\"width: 50%; vertical-align: bottom;\">\n                <p style=\"margin-bottom: 40px; font-weight: bold;\">Accepted & Agreed By:</p>\n                <p style=\"margin: 0; border-top: 1px solid #64748b; width: 80%; padding-top: 4px;\">Candidate Signature: <strong>{{employee_name}}</strong></p>\n                <p style=\"margin: 0; font-size: 11px; color: #64748b;\">Date: ____________________</p>\n            </td>\n            <td style=\"width: 50%; text-align: right; vertical-align: bottom;\">\n                <p style=\"margin-bottom: 40px; font-weight: bold;\">For {{company_name}}</p>\n                <p style=\"margin: 0; border-top: 1px solid #64748b; width: 80%; margin-left: 20%; padding-top: 4px;\">Authorized HR Representative</p>\n                <p style=\"margin: 0; font-size: 11px; color: #64748b;\">Human Resources Department</p>\n            </td>\n        </tr>\n    </table>\n</div>',NULL,NULL,'2026-08-05 10:00:24','2026-08-05 20:26:32'),
(2,'Appointment Letter','Appointment Letter','Official Letter of Appointment','<p>Date: {{current_date}}</p><p>To,<br><strong>{{employee_name}}</strong> (ID: {{employee_id}})</p><p>Dear {{employee_name}},</p><p>Further to your acceptance of our offer letter, we are pleased to appoint you as <strong>{{designation}}</strong> in <strong>{{company_name}}</strong> with effect from <strong>{{joining_date}}</strong>.</p><p>Your salary package will be <strong>{{salary}}</strong>. You will be on probation for a period of 6 months.</p><p>Welcome aboard!</p><p>Regards,<br><strong>HR Manager</strong><br>{{company_name}}</p>',NULL,NULL,'2026-08-05 10:00:24','2026-08-05 10:00:24'),
(3,'Experience Letter','Experience Letter','Service & Experience Certificate','<p>Date: {{current_date}}</p><p><strong>TO WHOMSOEVER IT MAY CONCERN</strong></p><p>This is to certify that <strong>{{employee_name}}</strong> (Emp ID: {{employee_id}}) was employed with <strong>{{company_name}}</strong> as a <strong>{{designation}}</strong> in the <strong>{{department}}</strong> department from <strong>{{joining_date}}</strong> to {{current_date}}.</p><p>During their tenure, we found them to be sincere, hard-working, and dedicated to their duties. We wish them all the best in their future endeavors.</p><p>For <strong>{{company_name}}</strong>,<br>Authorized Signatory</p>',NULL,NULL,'2026-08-05 10:00:24','2026-08-05 10:00:24'),
(4,'Relieving Letter','Relieving Letter','Relieving Letter','<p>Date: {{current_date}}</p><p>To,<br><strong>{{employee_name}}</strong><br>Emp ID: {{employee_id}}</p><p>Dear {{employee_name}},</p><p>With reference to your resignation, we hereby relieve you from your duties as <strong>{{designation}}</strong> at <strong>{{company_name}}</strong> effective {{current_date}}.</p><p>All company assets and dues have been settled. We appreciate your contributions and wish you success.</p><p>Sincerely,<br><strong>HR Department</strong><br>{{company_name}}</p>',NULL,NULL,'2026-08-05 10:00:24','2026-08-05 10:00:24'),
(5,'Internship Letter','Internship Letter','Internship Offer Letter','<p>Date: {{current_date}}</p><p>To,<br><strong>{{employee_name}}</strong></p><p>Dear {{employee_name}},</p><p>We are pleased to offer you an internship opportunity as <strong>{{designation}}</strong> in our <strong>{{department}}</strong> department starting on <strong>{{joining_date}}</strong> at <strong>{{company_name}}</strong>.</p><p>Stipend: {{salary}} per month.</p><p>Best Wishes,<br>{{company_name}}</p>',NULL,NULL,'2026-08-05 10:00:24','2026-08-05 10:00:24'),
(6,'Promotion Letter','Promotion Letter','Letter of Promotion','<p>Date: {{current_date}}</p><p>Dear {{employee_name}},</p><p>Congratulations! In recognition of your outstanding performance, we are pleased to promote you to <strong>{{designation}}</strong> in <strong>{{department}}</strong> with revised compensation of <strong>{{salary}}</strong>.</p><p>Keep up the great work!</p><p>For <strong>{{company_name}}</strong></p>',NULL,NULL,'2026-08-05 10:00:24','2026-08-05 10:00:24'),
(7,'Warning Letter','Warning Letter','Official Performance Warning Letter','<p>Date: {{current_date}}</p><p>To,<br><strong>{{employee_name}}</strong> (Emp ID: {{employee_id}})</p><p>This letter serves as a formal warning regarding your recent performance/attendance concerns. Please treat this as a serious matter to align with company policies.</p><p>Sincerely,<br>HR Department</p>',NULL,NULL,'2026-08-05 10:00:24','2026-08-05 10:00:24'),
(8,'Salary Increment Letter','Salary Increment Letter','Salary Revision Letter','<p>Date: {{current_date}}</p><p>Dear {{employee_name}},</p><p>We are glad to inform you that your monthly salary has been revised to <strong>{{salary}}</strong> effective immediately for your role as <strong>{{designation}}</strong>.</p><p>Congratulations!</p><p>{{company_name}} HR Team</p>',NULL,NULL,'2026-08-05 10:00:24','2026-08-05 10:00:24'),
(9,'Termination Letter','Termination Letter','Notice of Employment Termination','<p>Date: {{current_date}}</p><p>Dear {{employee_name}},</p><p>This letter is to inform you that your employment as <strong>{{designation}}</strong> with <strong>{{company_name}}</strong> is terminated effective {{current_date}}.</p><p>HR Department</p>',NULL,NULL,'2026-08-05 10:00:24','2026-08-05 10:00:24'),
(10,'No Objection Certificate','No Objection Certificate','No Objection Certificate (NOC)','<p>Date: {{current_date}}</p><p><strong>NO OBJECTION CERTIFICATE</strong></p><p>This is to certify that <strong>{{company_name}}</strong> has no objection to <strong>{{employee_name}}</strong> (Emp ID: {{employee_id}}), working as <strong>{{designation}}</strong>, applying for higher studies / passport / loan.</p><p>For {{company_name}}</p>',NULL,NULL,'2026-08-05 10:00:24','2026-08-05 10:00:24'),
(11,'Internship Completion Certificate','Internship Completion Certificate','Internship Completion Certificate','<p>Date: {{current_date}}</p><p><strong>INTERNSHIP COMPLETION CERTIFICATE</strong></p><p>This is to certify that <strong>{{employee_name}}</strong> has successfully completed an Internship as <strong>{{designation}}</strong> in the <strong>{{department}}</strong> department at <strong>{{company_name}}</strong>.</p><p>For {{company_name}}</p>',NULL,NULL,'2026-08-05 10:00:24','2026-08-05 10:00:24'),
(12,'Custom Letter','Custom Letter','Official Communication - {{company_name}}','<p>Date: {{current_date}}</p><p>To,<br><strong>{{employee_name}}</strong> (ID: {{employee_id}})</p><p>Dear {{employee_name}},</p><p>Write your custom text here...</p><p>Regards,<br><strong>{{company_name}}</strong></p>',NULL,NULL,'2026-08-05 10:00:24','2026-08-05 10:00:24');
/*!40000 ALTER TABLE `hr_document_templates` ENABLE KEYS */;
UNLOCK TABLES;
COMMIT;
SET AUTOCOMMIT=@OLD_AUTOCOMMIT;

